def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    border = Counter()
    for c in range(w):
        if grid[0][c] != bg:
            border[grid[0][c]] += 1
        if grid[h - 1][c] != bg:
            border[grid[h - 1][c]] += 1
    for r in range(1, h - 1):
        if grid[r][0] != bg:
            border[grid[r][0]] += 1
        if grid[r][w - 1] != bg:
            border[grid[r][w - 1]] += 1
    bar = border.most_common(1)[0][0]

    dots = [(r, c) for r in range(h) for c in range(w)
            if grid[r][c] != bg and grid[r][c] != bar]
    if not dots:
        return [row[:] for row in grid]
    dot_color = grid[dots[0][0]][dots[0][1]]
    out = [row[:] for row in grid]

    edges = {"top": [], "bottom": [], "left": [], "right": []}
    for c in range(w):
        if grid[0][c] == bar:
            edges["top"].append(c)
        if grid[h - 1][c] == bar:
            edges["bottom"].append(c)
    for r in range(h):
        if grid[r][0] == bar:
            edges["left"].append(r)
        if grid[r][w - 1] == bar:
            edges["right"].append(r)

    # Each marked edge segment sends a ray inward. Rays stop at a bar
    # cell, or mark a dot with 4.
    n = len(dots)
    for side, positions in edges.items():
        for x in sorted(set(positions))[-n:]:
            if side == "top":
                r, dr, c, dc = 1, 1, x, 0
            elif side == "bottom":
                r, dr, c, dc = h - 2, -1, x, 0
            elif side == "left":
                r, dr, c, dc = x, 0, 1, 1
            else:
                r, dr, c, dc = x, 0, w - 2, -1

            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == bar:
                    break
                if (r, c) in dots:
                    out[r][c] = 4
                    break
                out[r][c] = dot_color
                r += dr
                c += dc

    return out
